  CONSTRAINT fk_6 FOREIGN KEY (ProductId) REFERENCES dbo.dim_product (ProductId),
  CONSTRAINT fk_5 FOREIGN KEY (SupplierId) REFERENCES dbo.dim_supplier (SupplierId)
)
